"""matplotlib.artist — base Artist class."""

import sys as _sys
import numpy as _np


# Shared no-op fallback for unknown Artist methods. Since Axes, Figure
# and many other classes inherit from Artist, this single fallback
# covers a huge surface.
_artist_warned = set()

def _artist_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _artist_warned:
        _artist_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] artist.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Artist:
    """Base class for all visual elements."""
    __getattr__ = _artist_getattr_fallback

    def __init__(self):
        self._alpha = None
        self._visible = True
        self._label = ''
        self._zorder = 0
        self._transform = None
        self._clip_on = True
        self._animated = False
        self._picker = None
        self._rasterized = None
        self._sketch_params = None
        self._path_effects = []
        self._snap = None
        self._stale = True
        self.axes = None
        self.figure = None

    def get_alpha(self): return self._alpha
    def set_alpha(self, a): self._alpha = a
    def get_visible(self): return self._visible
    def set_visible(self, v): self._visible = v
    def get_label(self): return self._label
    def set_label(self, l): self._label = str(l)
    def get_zorder(self): return self._zorder
    def set_zorder(self, z): self._zorder = z
    def get_transform(self): return self._transform
    def set_transform(self, t): self._transform = t
    def get_clip_on(self): return self._clip_on
    def set_clip_on(self, b): self._clip_on = b
    def get_clip_box(self): return None
    def set_clip_box(self, box): pass
    def get_clip_path(self): return None
    def set_clip_path(self, path, transform=None): pass
    def get_animated(self): return self._animated
    def set_animated(self, b): self._animated = b
    def get_picker(self): return self._picker
    def set_picker(self, p): self._picker = p
    def get_rasterized(self): return self._rasterized
    def set_rasterized(self, r): self._rasterized = r
    def get_sketch_params(self): return self._sketch_params
    def set_sketch_params(self, scale=None, length=None, randomness=None):
        self._sketch_params = (scale, length, randomness)
    def get_path_effects(self): return self._path_effects
    def set_path_effects(self, effects): self._path_effects = effects
    def get_snap(self): return self._snap
    def set_snap(self, snap): self._snap = snap
    def get_figure(self): return self.figure
    def set_figure(self, fig): self.figure = fig
    def get_axes(self): return self.axes
    def get_children(self): return []
    def contains(self, mouseevent): return False, {}
    def pick(self, mouseevent): pass

    def pchanged(self):
        """Notify registered observers that this artist has changed.
        Mirrors upstream's callback dispatch."""
        for cb in getattr(self, '_artist_callbacks', []) or []:
            if cb is not None:
                try: cb(self)
                except Exception: pass

    def remove(self): pass
    def stale_callback(self, *args): pass

    def findobj(self, match=None, include_self=True):
        """Walk this artist's subtree, returning artists that satisfy
        ``match`` (a class or predicate). Mirrors upstream behaviour."""
        results = [self] if include_self else []
        for child in self.get_children() or []:
            try:
                results.extend(child.findobj(match=match, include_self=True))
            except Exception:
                results.append(child)
        if match is None:
            return results
        if isinstance(match, type):
            return [r for r in results if isinstance(r, match)]
        return [r for r in results if callable(match) and match(r)]

    def get_window_extent(self, renderer=None): return None
    def set(self, **kwargs):
        for k, v in kwargs.items():
            setter = getattr(self, f'set_{k}', None)
            if setter:
                setter(v)
    def update(self, props):
        if isinstance(props, dict):
            self.set(**props)

    def properties(self):
        """Return a dict of all ``getter`` properties on this artist by
        walking ``get_*`` methods and calling them (without args)."""
        out = {}
        for name in dir(self):
            if not name.startswith('get_'):
                continue
            attr = getattr(type(self), name, None)
            if attr is None or not callable(attr):
                continue
            try:
                # Skip getters that take required args.
                import inspect
                sig = inspect.signature(attr)
                params = [p for p in sig.parameters.values()
                          if p.kind in (p.POSITIONAL_OR_KEYWORD, p.POSITIONAL_ONLY)
                          and p.default is p.empty
                          and p.name not in ('self',)]
                if params:
                    continue
                out[name[4:]] = getattr(self, name)()
            except Exception:
                continue
        return out

    def update_from(self, other):
        """Copy presentation-related state from ``other`` onto self.
        Mirrors what upstream's :meth:`Artist.update_from` does for
        alpha / visibility / transform / clip / label / zorder."""
        for attr in ('alpha', 'visible', 'transform', 'clip_on',
                      'clip_box', 'clip_path', 'label', 'zorder',
                      'animated', 'rasterized', 'sketch_params',
                      'agg_filter', 'snap', 'url', 'gid', 'in_layout',
                      'path_effects'):
            getter = getattr(other, f'get_{attr}', None)
            setter = getattr(self, f'set_{attr}', None)
            if getter is None or setter is None:
                continue
            try:
                setter(getter())
            except Exception:
                pass

    def draw(self, renderer): pass
    def get_agg_filter(self): return None
    def set_agg_filter(self, f): pass
    def get_gid(self): return None
    def set_gid(self, gid): pass
    def get_url(self): return None
    def set_url(self, url): pass


def getp(obj, property=None):
    """Get property (or all properties) of an artist."""
    if property:
        return getattr(obj, f'get_{property}', lambda: None)()
    return {}


def setp(obj, *args, **kwargs):
    """Set properties on an artist."""
    if isinstance(obj, (list, tuple)):
        for o in obj:
            setp(o, *args, **kwargs)
        return
    if hasattr(obj, 'set'):
        obj.set(**kwargs)


def get(obj, *args, **kwargs):
    return getp(obj, *args, **kwargs)


class ArtistInspector:
    """Discover an artist's ``set_*`` methods so docs/UIs can list the
    properties it accepts. Mirrors what upstream uses for ``setp(obj)``
    output with no arguments — a list of "settable" attribute names."""

    def __init__(self, o):
        self.o = o if not isinstance(o, type) else o
        self.oorig = o
        self.aliases = {}

    def get_aliases(self):
        return self.aliases

    def get_setters(self):
        """All ``set_<attr>`` methods on the artist."""
        return sorted(name[4:] for name in dir(self.o)
                      if name.startswith('set_')
                      and callable(getattr(self.o, name, None)))

    def get_valid_values(self, attr):
        """Best-effort docstring excerpt for ``set_<attr>``."""
        fn = getattr(self.o, f'set_{attr}', None)
        if fn is None or fn.__doc__ is None:
            return ''
        # Return the first paragraph of the docstring.
        for line in (fn.__doc__ or '').split('\n\n'):
            line = line.strip()
            if line:
                return line
        return ''


# ─── Added: missing public names from upstream artist.py ───────────


def allow_rasterization(draw):
    """Decorator upstream wraps every backend's ``draw`` with — turns
    on Agg's rasterization when the artist asked for it. The shim has
    no Agg backend, so we just pass-through.
    """
    def _wrap(artist, renderer, *args, **kwargs):
        return draw(artist, renderer, *args, **kwargs)
    _wrap.__name__ = getattr(draw, '__name__', '_wrap')
    return _wrap


def kwdoc(obj):
    """Build a docstring describing the keyword arguments accepted by
    ``obj`` (an Artist class or instance). Used by upstream's ``@docstring``
    decorator to embed setter docs into class docstrings.

    The shim doesn't ship per-setter docstrings, so we return an empty
    string — callers concatenate the result onto the host docstring and
    won't crash.
    """
    return ''


# ── Sketch-params helper ──────────────────────────────────────────


def _XYPair(x, y):
    """Convenience used internally by upstream — returns a tiny pair
    object exposed for any caller that introspects matplotlib.artist."""
    return (x, y)


# ─── Added: missing Artist methods ─────────────────────────────────


def _attach_artist_methods(cls):
    """Fill in the remaining :class:`Artist` API surface."""

    def add_callback(self, func):
        if not hasattr(self, '_artist_callbacks'):
            self._artist_callbacks = []
        self._artist_callbacks.append(func)
        return len(self._artist_callbacks) - 1

    def remove_callback(self, cid):
        if hasattr(self, '_artist_callbacks') and 0 <= cid < len(self._artist_callbacks):
            self._artist_callbacks[cid] = None

    def convert_xunits(self, x):  return x
    def convert_yunits(self, y):  return y
    def format_cursor_data(self, data): return str(data)
    def get_cursor_data(self, event): return None
    def have_units(self):         return False
    def is_transform_set(self):   return self._transform is not None
    def get_in_layout(self):      return getattr(self, '_in_layout', True)
    def set_in_layout(self, b):   self._in_layout = bool(b)
    def get_mouseover(self):      return getattr(self, '_mouseover', False)
    def set_mouseover(self, b):   self._mouseover = bool(b)
    def get_tightbbox(self, renderer=None): return None
    def get_window_extent(self, renderer=None): return None
    def pickable(self):           return self._picker is not None
    def sticky_edges(self):       return ((), ())

    @property
    def stale(self):              return getattr(self, '_stale', True)
    @stale.setter
    def stale(self, b):           self._stale = bool(b)

    # ``axes`` property — Artist.__init__ sets it as instance attribute
    # which conflicts on subclasses (e.g. Figure). Provide a property
    # with passthrough setter so child classes can override cleanly.
    def _axes_get(self):          return getattr(self, '_axes', None)
    def _axes_set(self, ax):      self._axes = ax

    _l = locals()
    for n in ('add_callback', 'remove_callback', 'convert_xunits',
              'convert_yunits', 'format_cursor_data', 'get_cursor_data',
              'have_units', 'is_transform_set', 'get_in_layout',
              'set_in_layout', 'get_mouseover', 'set_mouseover',
              'get_tightbbox', 'get_window_extent', 'pickable',
              'sticky_edges'):
        if n in _l:
            setattr(cls, n, _l[n])


_attach_artist_methods(Artist)


# ─── ArtistInspector helpers (real introspection, not stubs) ───────


def _ai_aliased_name(self, s):
    aliases = self.get_aliases()
    return aliases.get(s, s)


def _ai_aliased_name_rest(self, s, target=''):
    return f'{self.aliased_name(s)}: {target}' if target else self.aliased_name(s)


def _ai_is_alias(self, prop):
    return prop in self.get_aliases()


def _ai_number_of_parameters(self, func):
    import inspect
    try:
        sig = inspect.signature(func)
        return len([p for p in sig.parameters.values()
                    if p.kind in (p.POSITIONAL_OR_KEYWORD, p.POSITIONAL_ONLY,
                                   p.KEYWORD_ONLY)])
    except (ValueError, TypeError):
        return 0


def _ai_pprint_getters(self):
    """List of '    foo = <value>' lines, one per ``get_*`` getter."""
    out = []
    for name in sorted(dir(self.o)):
        if not name.startswith('get_'): continue
        try:
            v = getattr(self.o, name)()
            out.append(f'    {name[4:]} = {v!r}')
        except Exception:
            continue
    return out


def _ai_pprint_setters(self, prop=None, leadingspace=2):
    """Indented list of setter signatures (``set_foo: ...``)."""
    setters = self.get_setters() if prop is None else [prop]
    pad = ' ' * leadingspace
    return [f'{pad}{s}: {self.get_valid_values(s)}' for s in setters]


def _ai_pprint_setters_rest(self, prop=None, leadingspace=4):
    return _ai_pprint_setters(self, prop=prop, leadingspace=leadingspace)


def _ai_properties(self):
    """Return ``{attr: get_attr()}`` for every settable property."""
    out = {}
    for s in self.get_setters():
        getter = getattr(self.o, f'get_{s}', None)
        if getter is None: continue
        try: out[s] = getter()
        except Exception: pass
    return out


ArtistInspector.aliased_name           = _ai_aliased_name
ArtistInspector.aliased_name_rest      = _ai_aliased_name_rest
ArtistInspector.is_alias               = _ai_is_alias
ArtistInspector.number_of_parameters   = _ai_number_of_parameters
ArtistInspector.pprint_getters         = _ai_pprint_getters
ArtistInspector.pprint_setters         = _ai_pprint_setters
ArtistInspector.pprint_setters_rest    = _ai_pprint_setters_rest
ArtistInspector.properties             = _ai_properties


# ─── Class-level descriptors for Artist attributes ─────────────────
# Class-level properties so ``hasattr(Artist, 'zorder')`` works even
# though the instance attrs live on `self`. Each backs onto an
# underscored private attr so __init__'s direct assignment still flows
# through the setter cleanly.


Artist.zorder    = property(lambda self: getattr(self, '_zorder', 0),
                             lambda self, v: setattr(self, '_zorder', v))
Artist.stale     = property(lambda self: getattr(self, '_stale', True),
                             lambda self, v: setattr(self, '_stale', v))
Artist.mouseover = property(lambda self: getattr(self, '_mouseover', False),
                             lambda self, v: setattr(self, '_mouseover', v))


def _ar_get_transformed_clip_path_and_affine(self):
    """Return ``(clip_path_in_data_coords, affine)`` if a clip_path is
    set, else ``(None, None)``."""
    cp = self.get_clip_path()
    if cp is None:
        return None, None
    tr = self.get_transform()
    return cp, tr


Artist.get_transformed_clip_path_and_affine = _ar_get_transformed_clip_path_and_affine
